# flagged: documented but never used in recipes
FLAG={'3-52':('Rue','Rue is unsafe in pregnancy and can irritate the skin; documented for history only, never used in recipes.'),'3-36':('Pennyroyal','Pennyroyal is toxic (especially its oil) and unsafe in pregnancy; history only.'),'3-26':('Wormwood','Wormwood contains thujone; history only, never used in recipes.')}
PROP=re.compile(r'warm|cool|cold|digest|stomach|bowel|belly|cough|throat|sleep|urine|wind|nourish|strength|appetite|sweet|sharp|bitter|astring|soft|laxative|thirst|chest|breath',re.I)
STOPMED=re.compile(r'cure|heal|illness|disease|kidney|spleen|liver|paraly|worm|hernia|convuls|sciatica|dysenter|genital|gangren|pustule|wound|bladder|jaundice|fever|pain|lung|dog|bite|menstru|abort|womb|private|uterus|venomous|bitten|poison|scorpion|serpent|ulcer|fistula|leprosy|gout|tumour|tumor|cancer|epilep|dropsy|eye salve|suppositor|pessar',re.I)
def clean(s): return re.sub(r'\s+',' ',re.sub(r'\n\d+\n|BOOK [A-Z]+[^\n]*\n|THE HERBAL OF DIOSCORIDES THE GREEK','\n',s)).strip()
roman=lambda b:['I','II','III','IV','V'][int(b)-1]
out=[]
def entry(cid,en,cat,kw,caution,safe):
    g,body=chap[cid]
    sug=re.search(r'SUGGESTED:\s*([^\n\[]+)',body); txt=clean(re.sub(r'^.*\n','',body,1))
    txt=re.sub(r'SUGGESTED:.*?(?=[A-Z][a-z]+ [a-z]+ [a-z]+)', '', txt,1)
    sents=re.split(r'(?<=[.;])\s+',txt)
    props=[s for s in sents if PROP.search(s) and not STOPMED.search(s) and 25<len(s)<260][:4]
    prep=[s for s in sents if re.search(r'boil|roast|cook|eaten|eat|food|bread|pickl|preserv|brine|wine|honey|vinegar|season|sauce|dried|pound',s,re.I) and not STOPMED.search(s) and 25<len(s)<260][:3]
    USE=re.compile(r'good for|good against|helps?|suitable (?:for|against)|eases?|relieves?|soothes?|settles?|expels? wind|stops?|strengthens?|nourish|digest|is diuretic|expels? urine|loosens?|binds? the|softens? the bowels',re.I)
    BADUSE=re.compile(r'FUCHS|FAGUET|THIEBAULT|— 1[5-9][0-9][0-9]|menstru|abort|womb|uterus|genital|private|pessar|suppositor|venomous|poison|conception|sterile|sex|semen|dead|embryo|birth',re.I)
    uses=[s for s in sents if USE.search(s) and not BADUSE.search(s) and 25<len(s)<240][:3]
    b,n=cid.split('-')
    return dict(id='D'+cid,ref=f'De Materia Medica {roman(b)}.{n}',book=int(b),chapter=n,greek=g.title(),name=en,category=cat,botanical=(sug.group(1).strip().rstrip(',') if sug else None),keywords=kw,recipeSafe=safe,uses=uses,caution=caution,properties=props,preparations=[p for p in prep if p not in props][:2],excerpt=txt[:420])
for cid,v in C.items():
    if cid in chap: out.append(entry(cid,v['en'],v['cat'],v['kw'],v['caution'],True))
    else: print('missing',cid)
for cid,(en,c) in FLAG.items(): out.append(entry(cid,en,'flagged',[en.lower()],c,False))
